import{_ as e,o as i,c as l,a3 as o}from"./chunks/framework.DjfA6S92.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"Collection/DozensOfVisits.md","filePath":"Collection/DozensOfVisits.md"}'),t={name:"Collection/DozensOfVisits.md"};function r(s,a,n,c,d,h){return i(),l("div",null,[...a[0]||(a[0]=[o('<h2 id="q-千万访问量的项目-前端需要注意些什么" tabindex="-1">Q: 千万访问量的项目，前端需要注意些什么？ <a class="header-anchor" href="#q-千万访问量的项目-前端需要注意些什么" aria-label="Permalink to &quot;Q: 千万访问量的项目，前端需要注意些什么？&quot;">​</a></h2><h2 id="a" tabindex="-1">A: <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A:&quot;">​</a></h2><p><code>Author: @liyuk, @heaven, @bailnl, @serge, @菩提大叔, @onion</code></p><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h3><ul><li>交互优化：请求时间过长、响应间隔过长；</li><li>日志埋点：生产环境操作埋点、报错处理；</li><li>异地容灾：cdn切换、后端环境、uat灰度；</li><li>CDN：容灾、备份、切换、迁移、渐进恢复、</li><li>减少事故、快速处理；</li><li>请求方面：客户端请求合并、顺序依赖、权限控制、大数据查询逻辑拆分、请求性能优化、减少服务器带宽和占用时间、迅速响应；</li><li>前端解耦、类似后端SOA；</li><li>版本控制：前端接口及资源的版本控制；</li></ul><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h3><ul><li>后端相关：负载均衡；</li><li>自动扩容，监控，报警，降级；</li><li>页面监控、错误上报、容灾；</li><li>数据一致性；</li><li>高并发；</li><li>资源共享；</li><li>版本控制：项目版本、接口版本；</li></ul><h2 id="roast" tabindex="-1">Roast: <a class="header-anchor" href="#roast" aria-label="Permalink to &quot;Roast:&quot;">​</a></h2><p>这个题是一个开放性问题，可以侧重于<code>安全</code>与<code>性能（请求）</code>相关的内容围绕回答。 需要再强调项目的类型是<code>2B</code>还是<code>2C</code>，各有侧重 条理上可以拆分为用户环境、前端部署、后端服务三个大点。</p>',9)])])}const f=e(t,[["render",r]]);export{_ as __pageData,f as default};
